1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_SURCHARGE_DIVISOR = 10;
3	
4	const BASE_PREMIUMS: Record<string, number> = {
5	  sword: 100,
6	  amulet: 60,
7	};
8	
9	export type ScenarioResult = { premium: number };
10	
11	type Item = { type: string };
12	
13	type Scenario = {
14	  steps: { items: Item[] }[];
15	};
16	
17	export const runScenario = (scenario: Scenario): { results: ScenarioResult[] } => {
18	  const items = scenario.steps[0].items;
19	  const insuredItemsPremium = items.reduce(
20	    (total, item) => {
21	      const base = BASE_PREMIUMS[item.type];
22	      return total + base + base / FIRST_INSURANCE_SURCHARGE_DIVISOR;
23	    },
24	    0,
25	  );
26	  const premium = Math.ceil(insuredItemsPremium + PROCESSING_FEE);
27	  return { results: [{ premium }] };
28	};
