input.new_string:
const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
};

// Divides rather than multiplying by a rate: `amount * 1.1` introduces
// floating-point error that shifts the spec's round-up in MHPCO's favour.
const percentOf = (percent: number, amount: number): number => (amount * percent) / 100;

