const items = scenario.steps[0].items;
const basePremium = items.reduce((total, item) => total + BASE_PREMIUMS[item.type], 0);
const firstInsuranceSurcharge = percentOf(FIRST_INSURANCE_SURCHARGE_PERCENT, basePremium);
const premium = Math.ceil(basePremium + firstInsuranceSurcharge + PROCESSING_FEE);

